import Link from "next/link";
import { PricingCards } from "@/components/pricing/pricing-cards";
import { PLANS, type PlanName } from "@/lib/plans";
import { localizedPrice, type PriceSearchParams } from "@/lib/localized-price";
import "./pricing-section.css";

export async function PricingSection({
  upgradeAction,
  startFreeAction,
  currentPlan,
  searchParams,
}: {
  upgradeAction: () => Promise<void>;
  startFreeAction: () => Promise<void>;
  currentPlan?: PlanName;
  searchParams: PriceSearchParams;
}) {
  const price = await localizedPrice(searchParams);
  return (
    <section
      id="pricing"
      className="outreach-lower text-[var(--tx)] [font-family:var(--font-plus-jakarta),_sans-serif] leading-[1.55] pricing-section scroll-mt-24 w-full mt-12 px-5 py-0 min-[640px]:mt-16 min-[640px]:px-4 min-[640px]:py-14 min-[760px]:mt-24 min-[760px]:pt-16 [background:var(--landing-bg)] text-[var(--pricing-text)] leading-[1.55]"
      aria-labelledby="pricing-title"
    >
      <div className="pricing-content max-w-310 mx-auto px-0 pt-8 pb-8 min-[640px]:px-[clamp(16px,4vw,44px)] min-[640px]:pt-11 min-[760px]:pt-12">
        <header className="pricing-heading text-center mb-10">
          <h2
            id="pricing-title"
            className="m-0 mx-auto max-w-[12em]! [font-family:var(--font-sans)] font-extrabold! tracking-[-0.035em]! text-[clamp(36px,6vw,58px)]! leading-[1.08]!"
          >
            Simple{" "}
            <em className="text-[var(--pricing-accent)] not-italic">pricing</em>{" "}
            for serious outreach.
          </h2>
          <p className="mt-3.5 mx-auto mb-0 max-w-[32em] text-[var(--pricing-muted)] text-[16px]">
            Start free with {PLANS.FREE.monthlyEmails} emails a month. Upgrade
            when you need more volume, reminders and CSV import.
          </p>
        </header>
        <PricingCards
          landing
          price={price}
          currentPlan={currentPlan}
          freeAction={
            <form action={startFreeAction}>
              <button
                className="button-interaction secondary-button pricing-button pricing-outline flex items-center justify-center cursor-pointer disabled:cursor-default"
                disabled={!!currentPlan}
              >
                {currentPlan === "FREE"
                  ? "Current plan"
                  : currentPlan === "PAID"
                    ? "Included in Premium"
                    : "Start free"}
              </button>
            </form>
          }
          premiumAction={
            <form action={upgradeAction}>
              <button
                className="pricing-button pricing-upgrade upgrade-shine relative isolate overflow-hidden flex items-center justify-center cursor-pointer disabled:cursor-default"
                disabled={currentPlan === "PAID"}
              >
                {currentPlan === "PAID" ? "Current plan" : "Upgrade to Premium"}
              </button>
            </form>
          }
        />
        <p className="pricing-foot mt-7 mx-0 mb-0 text-center text-[var(--pricing-muted)] text-[13px]">
          Sends from your Gmail. One email per person. Replies marked manually.{" "}
          <Link
            className="text-[var(--pricing-text)] font-semibold underline decoration-[var(--pricing-accent)] underline-offset-[3px] [[data-theme=dark]_&]:text-[var(--pricing-accent)]"
            href="/pricing"
          >
            See full comparison
          </Link>
        </p>
      </div>
    </section>
  );
}
